/* Farmer-first workspace. Values and rules are kept separate from biological diagnoses. */
const problems={
 temperature:{title:'Temperature changes',short:'Temperature',icon:'♧',question:'Is the water temperature changing?',description:'Track thermal changes and inspect rearing conditions. A reading alone does not establish thermal shock in fish.',steps:['Cross-check temperature at the station and inspect probe placement.','Record sunlight, rain, water exchanges and circulation changes.','Observe fish behavior; follow farm-approved adjustment procedures where needed.'],meaning:'Temperature tracks thermal changes; suitable conditions depend on species and life stage.'},
 DO:{title:'Low-oxygen risk',short:'Dissolved oxygen',icon:'◌',question:'Is dissolved oxygen decreasing?',description:'Track DO and its rate of change. No species-specific low-oxygen threshold has been approved for this farm.',steps:['Verify the DO reading and inspect the probe.','Observe fish and inspect oxygenation or circulation equipment, if installed.','Notify the responsible operator if verified readings exceed approved limits; do not wait for an experimental forecast.'],meaning:'DO is dissolved-oxygen concentration, not percent saturation. Legacy oxygen calculations based on conductivity are excluded.'},
 pH:{title:'Acid–base changes',short:'pH',icon:'◉',question:'Is pH changing unexpectedly?',description:'Track water acid–base conditions. The app does not determine causes or prescribe chemical dosing.',steps:['Cross-check pH and inspect probe calibration and cleanliness.','Record water exchanges, rainfall and water-treatment activities.','Request specialist review before any chemical adjustment.'],meaning:'A pH reading alone cannot establish ammonia toxicity or CO2 concentration; additional measurements are required.'},
 conductivity:{title:'Water-property changes',short:'Conductivity',icon:'ϟ',question:'Are water properties changing?',description:'Track conductivity changes that warrant inspection; this is not a salinity measurement in PSU.',steps:['Verify mS/cm units, cross-check the reading and confirm temperature compensation.','Compare concurrent water exchanges, rainfall and currents.','For salinity assessment, use a direct measurement or PSS-78 conversion with confirmed assumptions.'],meaning:'The source salinity key represents conductivity in mS/cm. This value alone does not establish salinity shock or pollution.'},
 turbidity:{title:'Reduced water clarity',short:'Turbidity',icon:'≋',question:'Is turbidity changing unexpectedly?',description:'Track water clarity and sudden spikes. Do not automatically attribute them to uneaten feed, waste or disease.',steps:['Review images or field observations and cross-check turbidity.','Check probe fouling, bubbles, feeding activities and water disturbance.','Record sampling evidence and request operator review before selecting a response.'],meaning:'Turbidity in NTU cannot be converted to waste load or TSS without site-specific calibration.'}
};
let problemSettings={};try{problemSettings=JSON.parse(localStorage.getItem('aquatwin-problem-ranges-v1')||'{}')}catch{}
let scenarioState={};
function problemKey(){return active.startsWith('problem-')?active.slice(8):null}
function assessValue(key,value){const range=problemSettings[key];if(value==null)return {label:'No measurement',cls:'unknown',detail:'Inspect the measurement stream; missing data does not establish safety.'};if(!range)return {label:'No reference range set',cls:'unknown',detail:'No confirmed species- and life-stage-specific limits are available.'};if(value<range.low)return {label:'Below trial range',cls:'suspect',detail:'Verify against farm-approved limits before making a decision.'};if(value>range.high)return {label:'Above trial range',cls:'suspect',detail:'Verify against farm-approved limits before making a decision.'};return {label:'Within trial range',cls:'pass',detail:'This does not establish fish safety or compliance with all environmental requirements.'}}
function singleStatus(key){const q=C.qcAt(data.rows,cursor,key,cursor);return {q,assessment:assessValue(key,row().values[key])}}
function problemNav(){const links=[['overview','Farm overview',icons.overview],...Object.entries(problems).map(([k,p])=>['problem-'+k,p.title,icons.insights])];$('#nav').innerHTML=links.map(([id,label,icon])=>`<a href="#${id}" class="${active===id?'active':''}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">${icon}</svg><span>${label}</span></a>`).join('');$('.nav-label').textContent='5 MONITORING AREAS';$('.workspace small').textContent='Farm · 5 monitoring areas';$('.side-note').innerHTML='<span class="tiny-dot"></span>Farm monitoring assistant<p>Observe → simulate → review decisions.</p>';const bottom=$('.side-bottom');if(!$('#advancedTools')){const button=document.createElement('button');button.id='advancedTools';button.className='side-link';button.textContent='⚙ Tools & connections';button.onclick=()=>modal('Supporting tools',`<p>Technical tools remain available separately from the five monitoring areas.</p><div class="tabs">${[['twin','Digital Twin'],['ditto','Ditto connection'],['quality','Data QC'],['events','Events'],['lab','Testing'],['journal','Logbook'],['data','Sources & settings'],['architecture','Architecture & evidence']].map(([id,title])=>`<a class="button secondary" href="#${id}" onclick="document.querySelector('#modal').close()">${title}</a>`).join('')}</div>`);bottom.insertBefore(button,$('#aboutBtn'))}}
function overviewSimple(){const suspect=C.keys.filter(k=>[3,4,9].includes(singleStatus(k).q.flag)).length;const status=suspect?'Data needs review':'Measurements available for monitoring';return heading('FARM / MARINE FARM 2','One farm. Five monitoring areas.','Review the farm, explore a monitoring area and test a scenario before considering action.',`<button class="button secondary" data-go="journal">＋ Field record</button>`)+`<section class="farm-status"><div><span class="eyebrow">FARM OVERVIEW STATUS</span><h2>${status}</h2><p>${suspect?`${suspect}/5 measurement streams have QC flags requiring review.`:'No measurement streams currently have suspect, fail or missing QC flags.'} Fish-stock health has not been assessed.</p></div><div class="farm-status-meta"><strong>${date(row().ts)}</strong><span>Historical replay · UTC+7</span><span>Cage location, depth and fish stock: unconfirmed</span></div></section>`+`<div class="problem-grid">${Object.entries(problems).map(([key,p],i)=>{const {q,assessment}=singleStatus(key);return `<article class="problem-card"><div class="problem-card-top"><span class="problem-symbol">${p.icon}</span><span class="label">AREA 0${i+1}</span>${pill(q.flag)}</div><h2>${p.title}</h2><p class="small-copy">${p.question}</p><div class="problem-reading">${f(row().values[key])}<small>${data.params[key].unit}</small></div><span class="pill ${assessment.cls}">${assessment.label}</span><p class="section-note">${p.description}</p><button class="button secondary full-width" data-go="problem-${key}">Monitor · simulate · review →</button></article>`}).join('')}</div>`+frame('Water trends and monitoring time',chart(subset(),metric)+timeline(),'Choose a time: all five areas use the same snapshot.',metricSelector())+`<p class="section-note">Each indicator represents a monitoring area, not a unique cause. QC flags assess data; trial ranges and guidance do not replace farm procedures.</p>`}
function problemPage(key){const p=problems[key],value=row().values[key],{q,assessment}=singleStatus(key),previous=data.rows[cursor-1];let rate=null;if(previous&&previous.values[key]!=null&&value!=null&&row().gapMinutes>0&&row().gapMinutes<=30)rate=(value-previous.values[key])/(row().gapMinutes/60);const range=problemSettings[key];const baselineEligible=q.flag===1&&value!=null;return heading(`MONITORING AREA ${Object.keys(problems).indexOf(key)+1} / ${p.short.toUpperCase()}`,p.title,p.description,`<button class="button secondary" data-go="overview">← Farm overview</button>`)+`<div class="notice"><span>ⓘ</span><div>${p.meaning} Currently viewing <strong>${date(row().ts)}</strong>, historical data in UTC+7.</div></div><div class="problem-summary"><div class="card"><span class="label">OBSERVED MEASUREMENT</span><div class="problem-reading">${f(value)}<small>${data.params[key].unit}</small></div>${pill(q.flag)}</div><div class="card"><span class="label">TRIAL-RANGE ASSESSMENT</span><h3 style="margin-top:18px">${assessment.label}</h3><p class="small-copy">${assessment.detail}</p></div><div class="card"><span class="label">CHANGE BETWEEN TWO SAMPLES</span><div class="problem-reading">${rate==null?'—':(rate>0?'+':'')+f(rate,2)}<small>${data.params[key].unit||'pH'}/hour</small></div><p class="section-note">Finite difference, not a cause or forecast.</p></div></div>`+frame('History '+p.short.toLowerCase(),chart(subset(),key)+timeline(),'Original readings and gaps are preserved; suspect QC points are marked.')+`<div class="two-col"><div>${frame('1. Scenario assessment',`<p class="small-copy">Enter a hypothetical value to explore the assessment. This does not model the effects of aeration, chemicals or water exchange.</p><form id="scenarioForm"><div class="form-grid"><div class="field"><label for="scenarioValue">${p.short} hypothetical (${data.params[key].unit||'unitless'})</label><input id="scenarioValue" name="value" type="number" step="any" required value="${scenarioState[key]?.value??value??''}"></div><div class="field"><label for="scenarioHorizon">Scenario time</label><select id="scenarioHorizon" name="horizon"><option value="15">After 15 minutes (assumed)</option><option value="30">After 30 minutes (assumed)</option><option value="60">After 60 minutes (assumed)</option></select></div></div><div class="form-actions"><button class="button" type="submit">▷ Evaluate scenario</button></div></form><div id="problemScenario"></div>`)}${frame('2. Reference forecast',baselineEligible?`<div class="label">BENCHMARK: PERSISTENCE</div><div class="problem-reading">${f(value)}<small>${data.params[key].unit}</small></div><p class="small-copy">Experimental next-sample forecast (~15 minutes at the source cadence). It equals the current reading and does not model biological responses.</p><p class="annotation">Not independently validated; no verified uncertainty interval. Do not use this forecast to trigger alerts or operational decisions.</p>`:`<span class="pill unknown">Forecast not generated</span><p class="small-copy">The current measurement is missing or has not passed QC. Verify it first; last_good is not substituted and called a forecast.</p>`)} </div><div>${frame('3. Operator decision guidance',`<span class="pill ${q.flag===1?'unknown':'suspect'}">${q.flag===1?'Inspection guidance':'Verify the measurement first'}</span>${p.steps.map((s,i)=>`<div class="step"><span class="step-num">${i+1}</span><div>${s}</div></div>`).join('')}<p class="annotation">No commands are sent to equipment. The responsible operator must approve any farm adjustment procedure.</p><button class="button secondary full-width" id="recordDecision">＋ Record a decision / inspection</button>`)}${frame('Trial reference range',`<p class="small-copy">Leave blank if unknown. This range is for browser-local scenarios only; it does not become a farm-approved biological threshold.</p><form id="rangeForm"><div class="form-grid"><div class="field"><label for="rangeLow">Lower limit</label><input id="rangeLow" name="low" type="number" step="any" required value="${range?.low??''}"></div><div class="field"><label for="rangeHigh">Upper limit</label><input id="rangeHigh" name="high" type="number" step="any" required value="${range?.high??''}"></div></div><div class="form-actions"><button class="button secondary" type="submit">Save trial range</button><button class="text-link" type="button" id="clearRange">Clear trial range</button></div></form>`)} </div></div>`}
function renderScenario(key){const s=scenarioState[key];if(!s)return;const a=assessValue(key,s.value),current=row().values[key];$('#problemScenario').innerHTML=`<div class="divider"></div><span class="pill ${a.cls}">SIMULATED · ${a.label}</span><p class="small-copy">Hypothetical value: <strong>${f(s.value)} ${data.params[key].unit}</strong> · sau ${s.horizon} minutes in this scenario.<br>Difference from the current reading: ${current==null?'unavailable':f(s.value-current)}.<br>${a.detail}</p><p class="section-note">This is a user-defined input, not a forecast. Observed states and the Ditto snapshot remain unchanged.</p>`}
const technicalRender=render;
render=function(){const key=problemKey();if(active==='overview'){$('#breadcrumb').textContent='Farm overview';$('#page').innerHTML=overviewSimple();bind()}else if(problems[key]){$('#breadcrumb').textContent=problems[key].title;$('#page').innerHTML=problemPage(key);bind();renderScenario(key);$('#scenarioForm').onsubmit=e=>{e.preventDefault();const v=Number($('#scenarioValue').value);if(!Number.isFinite(v))return toast('Invalid hypothetical value.');scenarioState[key]={value:v,horizon:Number($('#scenarioHorizon').value)};renderScenario(key)};$('#rangeForm').onsubmit=e=>{e.preventDefault();const low=Number($('#rangeLow').value),high=Number($('#rangeHigh').value);if(!Number.isFinite(low)||!Number.isFinite(high)||low>=high)return toast('The lower limit must be smaller than the upper limit.');const next={...problemSettings,[key]:{low,high,status:'user_trial_only'}};try{localStorage.setItem('aquatwin-problem-ranges-v1',JSON.stringify(next));problemSettings=next;render();toast('Trial range saved; it is not a farm-approved threshold.')}catch{toast('Unable to save settings.')}};$('#clearRange').onclick=()=>{const next={...problemSettings};delete next[key];try{localStorage.setItem('aquatwin-problem-ranges-v1',JSON.stringify(next));problemSettings=next;render()}catch{toast('Unable to save settings.')}};$('#recordDecision').onclick=()=>{modal('Inspection record: '+problems[key].short,`<form id="decisionForm"><div class="field"><label>Responsible operator</label><input name="owner" required maxlength="100"></div><div class="spacer"></div><div class="field"><label>Actual observations and decisions</label><textarea name="note" required maxlength="3000"></textarea></div><p class="small-copy">Record actual observations separately from scenarios. Saved only in this browser.</p><button class="button" type="submit">Save to logbook</button></form>`);$('#decisionForm').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));if(!values.owner.trim()||!values.note.trim())return;if(saveJournal({id:crypto.randomUUID(),type:'inspection',problem:key,time:row().ts,owner:values.owner,note:values.note,target:row().site,status:'Recorded by operator',sourceSnapshot:row().id,createdAt:new Date().toISOString()})){$('#modal').close();toast('Record saved.')}}}}else technicalRender();problemNav()};
